INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13246, 'koKR', 'Dowód zgonu: Keristrasza', 'Znasz historię Keristraszy?$B$BWiesz, jak przyczyniła się do zgładzenia Saragosy, małżonki Malygosa? I jak on w zamian wziął Keristraszę za swoją małżonkę, zamrażając ją w bryle lodu?$B$BDowiedzieliśmy się, że Malygos łamie jej wolę swoją magią. Doprowadziło ją to do obłędu.$B$B$N, musisz udać się do Nexusa w Mrozarze i położyć jej kres, zanim zostanie całkowicie przeciągnięta na jego stronę.$B$BChoć to mnie smuci, muszę nalegać, byś $gprzyniósł:przyniosła; mi jej serce jako dowód.', 'Arcymag Lan\'dalock w Dalaranie chce, abyś $gwrócił:wróciła; ze złamanym sercem Keristraszy.$B$BTo zadanie można ukończyć wyłącznie na poziomie heroicznym.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13246, 'koKR', 'Godne pożałowania, ale absolutnie konieczne.$b$bKirin Tor nie mógł sobie pozwolić, by znamienita czerwona smoczyca wpadła w ręce naszego największego wroga. Gdyby Malygos użył jej przeciwko nam w wojnie o Nexus, skutki byłyby druzgocące.$b$bŻałuję tylko, że nie mogliśmy jej zamiast tego ocalić.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13246, 'koKR', 'Gdybyśmy sądzili, że istnieje sposób, by ją odkupić, nie prosilibyśmy cię o odebranie jej życia.$b$bWiemy jednak, jak potężne stało się władanie Malygosa nad magią. Dzięki manipulacjom liniami mocy Azeroth nie ma sobie równych w sprawach tajemnych.', 0);
